mapper.select:
SELECT COUNT(*)
FROM sys_role
WHERE role_name = #{roleName}
AND id != #{excludeId}

SELECT COUNT(*)
FROM sys_role
WHERE role_code = #{roleCode}
AND id != #{excludeId}

mapper.update:
UPDATE sys_role
SET role_name = #{roleName},
    remark = #{remark},
    updated_at = #{updatedAt},
    updated_by = #{updatedBy}
WHERE id = #{id}

UPDATE sys_role
SET status = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM sys_user_role
WHERE role_id = #{roleId}
